import { FormField, type FormFieldConfig } from "@/components/formfield";
import { flowRibbonGeometry } from "@/components/formfield/geometries/flow-ribbon";

const FlowRibbonFieldGeometries = [flowRibbonGeometry] as const;

export const FlowRibbonFieldConfig = {
  "version": 1,
  "shape": "flow-ribbon",
  "theme": {
    "background": "#000000",
    "star": "#FFFFFF",
    "glow": "#FFFFFF"
  },
  "motion": {
    "flowSpeed": 1,
    "pointScale": 1,
    "morphDuration": 1.35
  },
  "effects": {
    "hoverRadius": 220,
    "hoverIntensity": 1,
    "trailIntensity": 1
  },
  "interaction": {
    "enabled": false,
    "holdMode": "magnet"
  }
} satisfies FormFieldConfig;

export function FlowRibbonField() {
  return (
    <div style={{ width: "100%", minHeight: 420, aspectRatio: "1 / 1" }}>
      <FormField config={FlowRibbonFieldConfig} geometries={FlowRibbonFieldGeometries} />
    </div>
  );
}
